<script setup lang="ts">
import { onMounted, ref } from "vue";
import { RefreshCw, Play, Scale, Check, X } from "@lucide/vue";
import type { AnswerExperimentDecision, AnswerRunView } from "@/api/answerExperiment";
import { compareAnswerExperiments, decideAnswerExperiment, getAnswerExperimentRuns, resumeAnswerExperiment, startAnswerExperiment } from "@/api/answerExperiment";
const runs=ref<AnswerRunView[]>([]), name=ref("回答引用基线"), baseline=ref(""), candidate=ref(""), comparison=ref<any>(null), busy=ref(false), error=ref("");
async function refresh(){busy.value=true;try{runs.value=await getAnswerExperimentRuns();}catch(e:any){error.value=e?.response?.data?.message??"读取回答实验失败";}finally{busy.value=false;}}
async function start(){busy.value=true;try{await startAnswerExperiment(name.value);await refresh();}catch(e:any){error.value=e?.response?.data?.message??"启动回答实验失败";}finally{busy.value=false;}}
async function resume(id:string){busy.value=true;try{await resumeAnswerExperiment(id);await refresh();}catch(e:any){error.value=e?.response?.data?.message??"恢复回答实验失败";}finally{busy.value=false;}}
async function compare(){if(!baseline.value||!candidate.value)return;try{comparison.value=await compareAnswerExperiments(baseline.value,candidate.value);}catch(e:any){error.value=e?.response?.data?.message??"比较回答实验失败";}}
async function decide(decision:AnswerExperimentDecision){if(!baseline.value||!candidate.value)return;try{await decideAnswerExperiment(candidate.value,baseline.value,decision,decision==="ADOPTED"?"回答质量与引用指标满足采用门槛":"回答实验候选未通过引用与知识依据护栏");await refresh();}catch(e:any){error.value=e?.response?.data?.message??"保存结论失败";}}
onMounted(refresh);
</script>
<template>
 <section class="answer-panel">
  <header><div><span>Stage 11.1</span><h2>回答与引用实验</h2><p>固定 5 题，逐题保存回答得分、知识依据和引用完整性；模型契约变化后可做基线/候选比较。</p></div><button class="icon-button" title="刷新" @click="refresh"><RefreshCw :size="16"/></button></header>
  <div class="answer-start"><input v-model="name" maxlength="100" aria-label="实验名称"><button @click="start" :disabled="busy"><Play :size="15"/>启动实验</button></div>
  <p v-if="error" class="error-banner" role="alert">{{ error }}</p>
  <div class="answer-runs" aria-live="polite"><article v-for="item in runs" :key="item.run.runId" :class="{selected:item.run.runId===baseline||item.run.runId===candidate}"><div><strong>{{ item.run.name }}</strong><small>{{ item.run.status }} · {{ item.succeededCaseCount }}/{{ item.run.totalCaseCount }} · {{ item.run.modelName }}</small></div><div class="run-actions"><button title="设为基线" @click="baseline=item.run.runId"><Scale :size="14"/>基线</button><button title="设为候选" @click="candidate=item.run.runId"><Check :size="14"/>候选</button><button v-if="item.run.status!=='SUCCEEDED'" title="恢复" @click="resume(item.run.runId)"><RefreshCw :size="14"/></button></div><dl v-if="item.run.report"><div><dt>通过率</dt><dd>{{ (item.run.report.passRate*100).toFixed(1) }}%</dd></div><div><dt>引用完整</dt><dd>{{ (item.run.report.citationCompleteness*100).toFixed(1) }}%</dd></div><div><dt>平均分</dt><dd>{{ item.run.report.averageOverallScore.toFixed(1) }}</dd></div></dl></article></div>
  <div v-if="baseline&&candidate" class="answer-compare"><button @click="compare"><Scale :size="15"/>比较选中运行</button><div v-if="comparison" class="metric-grid"><div v-for="metric in comparison.metrics" :key="metric.code"><span>{{ metric.label }}</span><strong :class="{bad:metric.higherIsBetter&&metric.delta<0}">{{ metric.delta>=0?'+':'' }}{{ (metric.delta*100).toFixed(1) }}{{ metric.code==='latencyP95Ms'?' ms':'' }}</strong></div></div><p v-if="comparison" :class="comparison.safeguardsPassed?'pass':'fail'">{{ comparison.safeguardsPassed?'通过回答依据与引用护栏':'未通过回答依据与引用护栏' }}</p><div v-if="comparison" class="decision-actions"><button @click="decide('ADOPTED')"><Check :size="14"/>采用候选</button><button @click="decide('REJECTED')"><X :size="14"/>回退候选</button></div></div>
 </section>
</template>
