dia(max-width:42rem){.answer-start{flex-direction:column}.answer-start input{min-width:0}.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}dl{gap:var(--space-md);flex-wrap:wrap}}
</style>
